          [item.id, item])).values()
      );
      uniqueChats.sort((a, b) => new Date(b.time) - new Date(a.time));
      state.recentChats = uniqueChats;
    },
  },
  actions: {
        // 从数据库加载最近聊天列表
    async loadRecentChats({ commit, rootState }) {
      try {
        const userId = rootState.user.id;
        const response = await axios.get(`${API_CONFIG.BASE_URL}/wss/chat/recent-chats/${userId}`, {
